import{_ as i,c as a,o,ae as n}from"./chunks/framework.DMK_uHmU.js";const h=JSON.parse('{"title":"Knowledge Base Configuration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Knowledge-Bases/knowledge-base.md","filePath":"Administration/AI-Management/Knowledge-Bases/knowledge-base.md"}'),t={name:"Administration/AI-Management/Knowledge-Bases/knowledge-base.md"};function l(s,e,r,d,c,u){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="knowledge-base-configuration-guide" tabindex="-1">Knowledge Base Configuration Guide <a class="header-anchor" href="#knowledge-base-configuration-guide" aria-label="Permalink to &quot;Knowledge Base Configuration Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#knowledge-base-configuration-guide">Knowledge Base Configuration Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-knowledge-base-configuration">Accessing Knowledge Base Configuration</a></li><li><a href="#knowledge-base-dialog-overview">Knowledge Base Dialog Overview</a></li><li><a href="#basic-information-section">Basic Information Section</a><ul><li><a href="#name-and-initials">Name and Initials</a></li><li><a href="#description">Description</a></li><li><a href="#group-access">Group Access</a></li><li><a href="#topics-and-tags">Topics and Tags</a></li></ul></li><li><a href="#ai-configuration-section">AI Configuration Section</a><ul><li><a href="#foundation-model-selection">Foundation Model Selection</a></li><li><a href="#creativity-settings">Creativity Settings</a></li></ul></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Knowledge Base Configuration dialog allows administrators to create and edit knowledge bases within the AI Assistant platform. A knowledge base (KB) is a collection of content that the AI uses to provide answers to user queries. This guide explains how to configure knowledge bases effectively using the KB Dialog interface.</p><h2 id="accessing-knowledge-base-configuration" tabindex="-1">Accessing Knowledge Base Configuration <a class="header-anchor" href="#accessing-knowledge-base-configuration" aria-label="Permalink to &quot;Accessing Knowledge Base Configuration&quot;">​</a></h2><p>The Knowledge Base Configuration dialog is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>This dialog appears when:</p><ul><li>Creating a new knowledge base by clicking &quot;Add KB&quot; in the Knowledge Base List View</li><li>Editing an existing knowledge base by clicking its name or the edit button</li></ul><h2 id="knowledge-base-dialog-overview" tabindex="-1">Knowledge Base Dialog Overview <a class="header-anchor" href="#knowledge-base-dialog-overview" aria-label="Permalink to &quot;Knowledge Base Dialog Overview&quot;">​</a></h2><p>The Knowledge Base Dialog is divided into two main columns:</p><p><strong>Left Column</strong>: Contains basic information fields</p><ul><li>Name and initials</li><li>Description</li><li>Group access settings</li><li>Topic and tag selection</li></ul><p><strong>Right Column</strong>: Contains AI and search configuration</p><ul><li>AI foundation model selection</li><li>Creativity settings</li><li>System instructions</li><li>Search configuration parameters</li><li>Sharing and visibility toggles</li></ul><h2 id="basic-information-section" tabindex="-1">Basic Information Section <a class="header-anchor" href="#basic-information-section" aria-label="Permalink to &quot;Basic Information Section&quot;">​</a></h2><h3 id="name-and-initials" tabindex="-1">Name and Initials <a class="header-anchor" href="#name-and-initials" aria-label="Permalink to &quot;Name and Initials&quot;">​</a></h3><ol><li><p><strong>Name</strong> (Required):</p><ul><li>The primary identifier for your knowledge base</li><li>Should be descriptive and unique</li><li>Appears in the knowledge base list and selection dropdowns</li><li>Maximum length: 255 characters</li></ul></li><li><p><strong>Initials</strong> (Required):</p><ul><li>Two-character identifier used for the knowledge base avatar</li><li>Automatically generated from the first two letters of the name</li><li>Can be manually overridden</li><li>Used in visual representations throughout the system</li></ul></li></ol><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>The description field provides context about the knowledge base&#39;s purpose and content:</p><ul><li>Helps users understand what information the KB contains</li><li>Appears in the knowledge base list and selection interfaces</li><li>Use clear, concise language explaining the KB&#39;s scope and use cases</li><li>Optional but strongly recommended</li></ul><h3 id="group-access" tabindex="-1">Group Access <a class="header-anchor" href="#group-access" aria-label="Permalink to &quot;Group Access&quot;">​</a></h3><p>Group Access controls which users can access this knowledge base:</p><ol><li><p><strong>Group Selection</strong>:</p><ul><li>Choose from existing groups in the system</li><li>Multiple groups can be selected</li><li>Only users belonging to selected groups will see this knowledge base</li><li>Groups are displayed as a tag list for easy management</li></ul></li><li><p><strong>Access Implications</strong>:</p><ul><li>Adding many groups increases visibility but may expose sensitive information</li><li>Limited group selection creates specialized access for specific teams</li><li>No groups selected means no users can access the knowledge base</li></ul></li></ol><h3 id="topics-and-tags" tabindex="-1">Topics and Tags <a class="header-anchor" href="#topics-and-tags" aria-label="Permalink to &quot;Topics and Tags&quot;">​</a></h3><p>Topics and tags help organize and categorize knowledge bases:</p><ol><li><p><strong>KB Topic</strong>:</p><ul><li>Single selection from predefined list</li><li>Used for major categorization</li><li>Helps organize knowledge bases in the list view</li><li>Optional field</li></ul></li><li><p><strong>KB Tags</strong>:</p><ul><li>Multiple selections from predefined list</li><li>Can create new tags if needed</li><li>Used for more granular categorization</li><li>Helps users find relevant knowledge bases</li><li>Optional field</li></ul></li></ol><h2 id="ai-configuration-section" tabindex="-1">AI Configuration Section <a class="header-anchor" href="#ai-configuration-section" aria-label="Permalink to &quot;AI Configuration Section&quot;">​</a></h2><h3 id="foundation-model-selection" tabindex="-1">Foundation Model Selection <a class="header-anchor" href="#foundation-model-selection" aria-label="Permalink to &quot;Foundation Model Selection&quot;">​</a></h3><p>Choose the AI model that will power this knowledge base:</p><ol><li><strong>AI Model</strong> (Required): <ul><li>Options: &quot;haiku&quot; or &quot;sonnet&quot;</li><li>Haiku: Optimized for speed and efficiency</li><li>Sonnet: Optimized for depth and complexity</li><li>Selection affects response quality and processing time</li></ul></li></ol><h3 id="creativity-settings" tabindex="-1">Creativity Settings <a class="header-anchor" href="#creativity-settings" aria-label="Permalink to &quot;Creativity Settings&quot;">​</a></h3><p>Control how creative or precise the AI responses should be:</p><ol><li><strong>Creativity</strong> (Required): <ul><li>Options: &quot;Creative,&quot; &quot;Balanced,&quot; or &quot;Precise&quot;</li><li>Creative: More varied and imaginative</li></ul></li></ol>',35)]))}const p=i(t,[["render",l]]);export{h as __pageData,p as default};
